    "correctAnswerText": "Cardiac tamponade secondary to pericardial effusion leading to obstructive shock and needs urgent echocardiography (ECHO) and drainage",
    "explanation": "Cardiac tamponade secondary to pericardial effusion leading to obstructive shock and needs urgent ECHO and drainage Rationale: MRSA septicemia can lead to collection in the pericardial space which if left unnoticed and monitored can lead to increase and cause obstructive shock. Urgent ECHO and relieving the tamponade can be lifesaving. Tension pneumothorax is unlikely if the child remained stable for over 10 h postextubation and with no PPV. Other options do not fit in.",
