    "correctAnswer": "C",
    "correctAnswerText": "Decrease respiratory rate to 10/min",
    "explanation": "In the waveform, expiratory flow has not reached baseline, and the next breath is initiated, which indicates air trapping and dynamic hyperventilation. In severe attacks of asthma, there is a severe limitation to expiratory flow of gases, and the goal of mechanical ventilation is to minimize auto-PEEP and limit pressures and not normalization of PaCO2 levels. It can be done by reducing the respiratory rate, tidal volumes, and by keeping low I:E ratios",
