    "id": 10308,
    "title": "PICU Critical Thinking Quiz — Quiz 3, Question 8",
    "scenario": "The recommendation for maximum cuff pressure of endotracheal (ET) tube in patients undergoing mechanical ventilation is:",
    "choices": {
      "A": "5–10 cm H2O",
      "B": "10–15 cm H2O",
      "C": "15–20 cm H2O",
      "D": "20–25 cm H2O",
      "E": "25–30 cm H2O."
    },
    "correctAnswer": "E",
    "correctAnswerText": "25–30 cm H2O.",
    "explanation": "The main purpose of the cuff around the ET tube is to prevent aspiration in the lung by creating a seal between the trachea and ET tube. Prolonged duration of high cuff pressure may also cause injury tracheal mucosa by reducing local perfusion. The cuff should be inflated just enough to prevent the leakage of gases around the cuff. In practice, it may be difficult to achieve balance, and hence, the use of a device to measure cuff pressures should be used. The recommended is 25–30 cm H2O.",
    "source": "PICU Critical Thinking Quiz",
    "category": "PICU Critical Thinking Quiz - Quiz 03",
