    "correctAnswer": "C",
    "correctAnswerText": "The initial emergency room doctor who intubated the patient",
    "explanation": "Meningococcal disease can rapidly cause shock and multiorgan failure. Hence, prevention is the most important component in managing this severe illness. Only close contacts that were potentially exposed to nasopharyngeal secretions early in the treatment course are recommended to receive antibiotic prophylaxis. Aggressive therapy for meningococcal disease has been shown to significantly improve outcomes. Early antibiotics, appropriate hemodynamic support, and referral to higher levels of care are all fundamental components of the management of invasive meningococcal infections.",
