    "correctAnswerText": "The patient needs to be rewarmed to 37°C (98.5°F) before consideration of the diagnosis of brain death.",
    "explanation": "Supplementary explanation from the supplied PowerPoint: Hypothermia is a confounder: core temperature must be normalised (>35 °C) before brain-death examination. 'Doll's eye positive' (eyes fixed in the orbit as the head turns) actually means absent oculocephalic reflex; spinal reflexes (e.g., Lazarus-type arm movements) can occur; ancillary tests are not mandatory.",
