    "scenario": "A 3-year-old boy with acute respiratory distress syndrome (ARDS) has a PaO2 of 50 mm Hg on a ventilator. After manipulating the ventilator settings and FiO2, his PaO2increases to 100 mm Hg. His hemoglobin is 10 g /dL. How much does the oxygen content change with the increase in PaO2?",
