    "explanation": "Supplementary explanation from the supplied PowerPoint: Hypoventilation (and low inspired PO2) lowers PAO2 and PaO2 equally, so the A–a gradient stays normal. Diffusion limit, V/Q mismatch and shunt all widen it.",
