    "title": "PICU Critical Thinking Quiz — Quiz 24, Question 8",
    "scenario": "A 3-year-old boy presents to the emergency department with signs of smoke inhalation but no superficial burns after he was pulled from a house fire. He is now intubated on pressure-controlled ventilation with an FiO2 of 0.4. His pulse oximeter reading is 100%, and his arterial blood gas values are as follows: pH 7.28, PaO2 150 mm Hg, PaCO2 35 mm Hg, oxygen saturation 100%, bicarbonate 16 mEq/L, and base deficit -8. What is the most likely cause of his metabolic acidosis?",
