    "id": 12410,
    "title": "PICU Critical Thinking Quiz — Quiz 24, Question 10",
    "scenario": "A 60-kg, 15-year-old boy who has severe bilateral pneumonia is on high frequency oscillatory ventilation with the following settings: mean airway pressure 32 cm H2O, delta P 75, oscillatory frequency 5 Hz, IT 33%. The patient has persistent hypercarbia and respiratory acidosis. After the frequency is gradually decreased to 3 Hz, the patient’s pH improves from 7.16 to 7.26 and his PaCO2 from 81 to 67 mm Hg. He has a 6.0 cuffed endotracheal tube in place with minimal air leak around it.Why does decreasing frequency increase CO2 removal?",
