    "scenario": "A 6-year old child with meningococcemia is on ventilator for 5 days and improving gradually. He is on Dopamine @ 10 mcg/kg/min, Adrenaline @ 0.09 mcg/kg/min and Noradrenaline @ 0.2 mcg/kg/min. His peripheries are cold and the vitals show: HR 178, BP 110/70. SpO2 97%. The CVP is 11 and SCVO2 is 75%. What is the best option at this stage?",
