    "id": 12607,
    "title": "PICU Critical Thinking Quiz — Quiz 26, Question 7",
    "scenario": "A 18-month-old girl is post op day 5 following a liver transplantation. She is on immunosuppresants-mycophenolate and tacrolimus. You are informed of a potassium report of 7.2 mEq/L and find tall T waves on the ECG monitor with occasional PVCs. She is hemodynamically stable otherwise. Which of the following is the quickest to reduce extracellular potassium levels?",
