    "correctAnswer": "D",
    "correctAnswerText": "Insulin/Dextrose infusion",
    "explanation": "Insulin/Dextrose infusion Hyperkalemia is an emergency. Calcium has membrane stabilizing effects and is needed in the emergent treatment of hyperkalemia but it doesnot effect the K levels. Sodabicarb has the onset of effect in 30-60 minutes while Insulin/Dextrose infusion starts its effect in 15-30 minutes. Insulin/Dextrose also causes a larger reduction in K levels compared to Sodabicarb, 1meq/l vs 0.5mEq/L.",
