    "correctAnswerText": "Oscillometric measurements are more likely to overestimate the systolic and underestimate the diastolic blood pressure.",
    "explanation": "Explanation: Automated Oscillometric blood pressure measurements are most commonly used in the PICUs. They are known to overestimate systolic and underestimate diastolic pressures (while mean blood pressure continues to correlate). The increase in systolic pressures moving towards periphery is because of amplification from reflected waves from the peripheries. This phenomenon is augmented in vasoconstrictive shock (option d). Pressure wave travels about 20 times faster than the flow wave (10m/sec vs 0.5m/sec). rs and explanation",
