    "scenario": "A 2-year-old child, known case of Spinal Muscular Atrophy presents with altered sensorium over last week. An arterial blood gas in room air shows PaO2 40 mmHg, PaCO2 80 mmHg, and pH of 7.29. Which of the following would explain her hypoxemia?",
