    "title": "PICU Critical Thinking Quiz — Quiz 30, Question 6",
    "scenario": "A 9 month old girl presents to the ED with stridor and respiratory distress for the last 2 days, no fevers. She was recently discharged from the hospital about 3 weeks back when she was admitted for sepsis, hypernatremia and encephalopathy needing mechanical ventilation for 4 days during her PICU stay. She was normal on discharge. A laryngoscopy done shows significant obstruction below the cords. Which of the following is likely to be associated with her condition?",
