    "correctAnswer": "D",
    "correctAnswerText": "Steroids before extubation reduces the risk of reintubation in adults",
    "explanation": "The Cochrane metanalysis and review on this topic (Khemani RG, Randolph A, Markovitz B. Corticosteroids for the prevention and treatment of post-extubation stridor in neonates, children and adults. Cochrane Database of Systematic Reviews 2009) shows that steroids may be of benefit in infants and children with airway abnormalities in reducing post extubation stridor. Steroids begun pre-extubation in adults does reduce the incidence of stridor but not of reintubation.",
    "source": "PICU Critical Thinking Quiz",
