    "id": 13010,
    "title": "PICU Critical Thinking Quiz — Quiz 30, Question 10",
    "scenario": "A 15 kg child is on Total parenteranl nutrition(TPN) in your unit. He is getting 1100ml of TPN in a day giving him a total of 1250 kcal, through a central line. He is on 2gm/kg of proteins and 3gm/kg of fats. All of the following statements are true for this child except ?",
