    "id": 13106,
    "title": "PICU Critical Thinking Quiz — Quiz 31, Question 6",
    "scenario": "A patient is admitted following an elective posterior spinal fusion. Besides kyphoscoliosis, the only pertinent history is sulfamethoxazole/trimethoprim allergy. In the operating room, he received packed red blood cells, 3 U; platelets, 4 U; and crystalloid fluid, 6 L, with only 2.4 L of urine output. He is admitted to the pediatric ICU on mechanical ventilation due to persistent hypoxemia. His admission chest radiograph shows diffuse pulmonary edema, so he is given a dose of furosemide. In the next 30 minutes he develops tachycardia, bronchospasm, and diffuse flushing. Which of the following is the most likely cause of his decompensation?",
    "choices": {
      "A": "Inadvertent administration of an aminoglycoside for postoperative wound prophylaxis",
      "B": "Allergic reaction to furosemide",
      "C": "Transfusion reaction",
      "D": "Worsening pulmonary edema from transfusion-related acute lung injury",
      "E": "Aspiration pneumonia"
    },
    "correctAnswer": "B",
    "correctAnswerText": "Allergic reaction to furosemide",
    "explanation": "Rationale: Recall that furosemide is a member of the sulfa family of drugs (similar to cotrimoxazole). The timing of the reaction (within 30 minutes of drug administration) is typical for allergic reactions. The symptomatology is consistent with acute release of histamine from triggered mast cells causing flushing, vasodilation (hence the tachycardia), and bronchospasm. Transfusion-related acute lung injury can manifest with pulmonary edema and persistent hypoxemia, though this is rarely associated with the allergic manifestations described in this case. Acute transfusion reactions can present with these manifestations, but the timing is much more proximate to the timing of the blood product transfusion. There would be no reason that an aminoglycoside should trigger an allergic reaction in a sulfa-allergic patient.",
    "source": "PICU Critical Thinking Quiz",
    "category": "PICU Critical Thinking Quiz - Quiz 31",
    "sourceNotes": [
      "Cross-reactivity between sulfonamide antibiotics and non-antibiotic sulfonamides such as furosemide is now considered uncommon."
    ],
    "references": [
      "Khilnani, JPCC 2014;1(4):324-328",
      "Original PICU QUIZ.pdf, PDF pages 148, 150."
    ]
